const TT_MC_ACCOUNTS = TT_DATA_DIR . '/accounts.json';
const TT_MC_OPERATIONS = TT_DATA_DIR . '/operations.json';
const TT_MC_MILLING_RATE = 3.0;

function mc_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function mc_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function mc_require_entity(array $u,string $entity,bool $write=false):void{if(($u['role']??'')==='Super Admin')return;$allowed=$write?(tt_user_can_access_entity($u,$entity,'Create')||tt_user_can_access_entity($u,$entity,'Edit')||tt_user_can_access_entity($u,$entity,'Approve')):tt_user_can_access_entity($u,$entity,'View');if(!$allowed)mc_out(['ok'=>false,'error'=>'You do not have permission for this legal entity.'],403);}
function mc_def():array{return ['revision'=>0,'journals'=>[],'events'=>[],'commodityBills'=>[],'managementCostingInputs'=>[],'managementCostingSheets'=>[],'managementCostingSheetHistory'=>[],'managementCostRates'=>[]];}
function mc_read_accounts():array{$h=@fopen(TT_MC_ACCOUNTS,'rb');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}return tt_accounts_source_decode((string)$raw,mc_def());}
function mc_read_ops():array{return mr_read_operations_source(TT_MC_OPERATIONS);}
function mc_op(array $ops,string $key):array{$raw=$ops['values'][$key]??'';if(!is_string($raw)||$raw==='')return [];$v=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(!is_array($v)||!array_is_list($v))throw new RuntimeException('Invalid operational rows.');return $v;}
function mc_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))mc_out(['ok'=>false,'error'=>'Costing sheet is available for TTI / BRM.'],422);return $v;}
function mc_norm(string $v):string{$v=preg_replace('/[^A-Z0-9]+/i',' ',trim($v))??trim($v);return strtoupper(trim(preg_replace('/\s+/',' ',$v)??$v));}
function mc_variety(string $v):string{$u=mc_norm($v);if(str_contains($u,'IRRI 6'))$b='IRRI-6';elseif(str_contains($u,'1121'))$b='1121';elseif(str_contains($u,'PK 386'))$b='PK-386';elseif(str_contains($u,'SUPER KERNEL'))$b='SUPER KERNEL';elseif(str_contains($u,'D 98'))$b='D-98';elseif(preg_match('/(^| )C 9( |$)/',$u))$b='C-9';else$b=$u?:'RICE';if(str_contains($u,'PARBOIL')||str_contains($u,'SELLA'))$b.=' PARBOIL';return $b;}
function mc_product(string $v):string{$u=mc_norm($v);if(str_starts_with($u,'B2 CSR'))return 'B2 CSR';if(str_starts_with($u,'B2')||str_contains($u,'B2 SORTEX')||str_contains($u,'BROKEN B2'))return 'B2';if($u==='CSR'||str_starts_with($u,'CSR '))return 'CSR';if($u==='POWDER'||str_contains($u,' POWDER'))return 'POWDER';if($u==='PADDY'||str_contains($u,' PADDY'))return 'PADDY';if($u==='B3'||str_starts_with($u,'B3 '))return 'B3';if($u==='OTHER')return 'OTHER';return $u;}
function mc_waste(string $v):bool{$u=mc_norm($v);return str_contains($u,'STONE')||str_contains($u,'SUTLI')||str_contains($u,'DUST');}
function mc_date(string $v):string{return mr_valid_date($v)?$v:'';}
function mc_sheet_id(string $entity,string $date,string $variety):string{return 'MCS-'.substr(hash('sha256',$entity.'|'.$date.'|'.$variety),0,18);}
function mc_rate_id(string $sheet,string $product):string{return 'MGR-'.substr(hash('sha256',$sheet.'|'.mc_norm($product)),0,20);}

function mc_bill_values(array $s):array{$out=[];foreach((array)($s['commodityBills']??[]) as $bill){if(!is_array($bill)||($bill['status']??'')!=='Verified / Posted')continue;$alloc=(array)($bill['receiptAllocations']??[]);if(!$alloc)continue;$base=0.0;foreach($alloc as $a)$base+=max(0,(float)($a['provisionalAmount']??0));$value=round((float)($bill['finalCommodityValue']??0)+(float)($bill['brokerageGross']??0),2);if($value<=0)continue;$used=0.0;$keys=array_keys($alloc);$last=end($keys);foreach($alloc as $i=>$a){$key=trim((string)($a['sourceKey']??''));if($key==='')continue;$part=$i===$last?round($value-$used,2):round($value*($base>0?max(0,(float)($a['provisionalAmount']??0))/$base:1/max(1,count($alloc))),2);$used=round($used+$part,2);$out[$key]=['value'=>$part,'billId'=>(string)($bill['id']??'')];}}return $out;}
function mc_receipts(array $s):array{$final=mc_bill_values($s);$rows=[];foreach((array)($s['events']??[]) as $e){if(!is_array($e)||($e['eventType']??'')!=='COMMODITY_RECEIPT_ACCEPTED')continue;$j=$s['journals'][(string)($e['journalId']??'')]??null;if(!is_array($j))continue;$m=is_array($j['meta']??null)?$j['meta']:[];$kg=(float)($m['payableWeightKg']??0);if($kg<=0)continue;$src=(string)($e['sourceKey']??'');$f=$final[$src]??null;$rows[]=['entity'=>(string)($e['entity']??$j['entity']??'TTI'),'date'=>(string)($j['date']??''),'varietyKey'=>mc_variety((string)($m['variety']??'')),'kg'=>$kg,'value'=>$f?(float)$f['value']:(float)($j['totalDebit']??0),'final'=>$f!==null,'sourceKey'=>$src];}return $rows;}
function mc_production(array $ops,string $entity='TTI'):array {
 $groups=[];foreach(mc_op($ops,'tt30prod') as $p){if(!is_array($p)||strtoupper((string)($p['entity']??'TTI'))!==$entity)continue;if(!mr_input_rows($p)&&!mr_output_rows($p))continue;$date=mc_date((string)($p['date']??''));if(!$date)continue;$variety=(string)($p['sourceVariety']??$p['displayName']??$p['variety']??'Rice');$vk=mc_variety($variety);$id=$entity.'|'.$date.'|'.$vk;if(!isset($groups[$id]))$groups[$id]=['id'=>$id,'date'=>$date,'variety'=>$variety,'varietyKey'=>$vk,'inputKg'=>0.,'inputComplete'=>true,'requiresInputStockCost'=>false,'readyKg'=>0.,'outputs'=>[]];$groups[$id]['requiresInputStockCost']=$groups[$id]['requiresInputStockCost']||!in_array(strtoupper((string)($p['inputStage']??'RAW')),['','RAW'],true);$actual=mr_consumption_kg($p);$groups[$id]['inputKg']+=$actual??0;$groups[$id]['inputComplete']=$groups[$id]['inputComplete']&&$actual!==null&&$actual>0;foreach(mr_output_rows($p) as $r){$name=$r['product'];$ready=$r['kind']==='finished';if($ready)$groups[$id]['readyKg']+=$r['kg'];if(!isset($groups[$id]['outputs'][$name]))$groups[$id]['outputs'][$name]=['product'=>$name,'kg'=>0.,'ready'=>$ready];$groups[$id]['outputs'][$name]['kg']+=$r['kg'];}}
 foreach($groups as &$g){$g['inputKg']=round($g['inputKg'],3);$g['readyKg']=round($g['readyKg'],3);$g['outputs']=array_values($g['outputs']);}unset($g);uasort($groups,static fn($a,$b)=>strcmp($a['date'],$b['date'])?:strcmp($a['varietyKey'],$b['varietyKey']));return $groups;
}

function mc_sales(array $ops,string $entity='TTI'):array {
 $rows=[];$n=0;
 foreach(['tt35localsales'=>'loads','tt35exportersale'=>'containers'] as $key=>$loadKey)foreach(mc_op($ops,$key) as $x){
  if(!is_array($x)||strtoupper((string)($x['entity']??'TTI'))!==$entity||!empty($x['deleted'])||in_array(strtolower((string)($x['status']??'')),['deleted','cancelled','canceled'],true))continue;
  $rate=(float)($x['rate']??0);$product=trim((string)($x['product']??$x['brand']??''));if($rate<=0||$product==='')continue;
  foreach((array)($x[$loadKey]??[]) as $load){
   if(!is_array($load)||!empty($load['deleted']))continue;$date=mc_date((string)($load['date']??$x['date']??''));
   $gross=(float)($load['weighbridgeGrossKg']??$load['weighbridgeKg']??$load['g']??$load['kg']??0);
   $net=(float)($load['netKg']??$load['net']??$load['kg']??max(0,$gross-(float)($load['emptyTareKg']??$load['tare']??0)));
   $kg=strtoupper((string)($x['billingWeightBasis']??'NET'))==='GROSS'?$gross:$net;
   if($date===''||$kg<=0)continue;
   $rows[]=['date'=>$date,'order'=>$n++,'rate'=>$rate,'kg'=>$kg,'product'=>$product,'key'=>mc_product($product),'reference'=>(string)($x['soda']??$x['ref']??''),'party'=>(string)($x['party']??$x['buyer']??''),'source'=>'Recorded delivered sale'];
  }
 }
 return $rows;
}
function mc_average_sale(array $sales,string $product,string $asOf):?array {
 $kg=0.;$value=0.;$refs=[];$latest='';$key=mc_product($product);
 foreach($sales as $sale){if($sale['key']!==$key||$sale['date']>$asOf)continue;$q=(float)$sale['kg'];$kg+=$q;$value+=$q*(float)$sale['rate'];$refs[]=$sale['reference'];$latest=max($latest,$sale['date']);}
 return $kg>0?['rate'=>$value/$kg,'date'=>$latest,'reference'=>implode(', ',array_unique($refs)),'party'=>'','soldKg'=>$kg]:null;
}
function mc_last_sale(array $sales,string $product,string $date):?array{$key=mc_product($product);$best=null;foreach($sales as $s){if(($s['key']??'')!==$key||($s['date']??'')>$date)continue;if($best===null||$s['date']>$best['date']||($s['date']===$best['date']&&$s['order']>$best['order']))$best=$s;}return $best;}
function mc_director_input(array $s,string $entity,string $date,string $vk):?array {
 // Reuse the same recipe prices and daily rates displayed in Directors; do not require optional stock links.
 $candidates=[];$profiles=json_decode((string)file_get_contents(__DIR__.'/../directors/costing-profiles.json'),true,512,JSON_THROW_ON_ERROR);
 foreach($profiles as $profile){if(($profile['commodity']??'RICE')!=='RICE'||mc_variety((string)($profile['name']??''))!==$vk)continue;foreach((array)($profile['outputs']??[]) as $o)if(($o['kind']??'')==='byproduct'&&is_numeric($o['ratePKRPerKg']??null)&&(float)$o['ratePKRPerKg']>0)$candidates[mc_product($o['product'])][]=(float)$o['ratePKRPerKg'];}
 $defaults=[];foreach($candidates as $product=>$rates){$rates=array_values(array_unique($rates));if(count($rates)===1)$defaults[$product]=$rates[0];}
 $rows=(array)($s['managementCostingInputs']??[]);
 foreach((array)($s['directorCostings']??[]) as $r){$i=(array)($r['input']??[]);$v='';foreach(['millVariety','marketRawProduct','name'] as $field)if(trim((string)($i[$field]??''))!==''){$v=$i[$field];break;}if($v==='')$v=(string)($r['name']??'');if($v===''||($i['commodity']??'RICE')!=='RICE')continue;$by=[];foreach((array)($i['outputs']??[]) as $o)if(($o['kind']??'')==='byproduct'&&is_numeric($o['ratePKRPerKg']??null))$by[mc_product($o['product'])]=(float)$o['ratePKRPerKg'];$factor=match($i['purchaseUnit']??'KG'){'MAUND'=>40.,'MT'=>1000.,default=>1.};$rows[]=['entity'=>$r['entity']??'','date'=>$r['date']??'','variety'=>$v,'rawRiceRate'=>(float)($i['cashPrice']??0)/$factor,'byProducts'=>$by];}
 $best=null;foreach($rows as $x){if(!is_array($x)||($x['entity']??'')!==$entity||($x['date']??'')>$date)continue;if(mc_variety((string)($x['variety']??$x['varietyKey']??''))!==$vk)continue;if($best===null||$x['date']>=$best['date'])$best=$x;}
 $result=$best??['entity'=>$entity,'date'=>'','variety'=>$vk,'rawRiceRate'=>0];$by=$defaults;foreach((array)($best['byProducts']??[]) as $name=>$rate)if(is_numeric($rate))$by[mc_product((string)$name)]=(float)$rate;
 if($vk==='IRRI-6'){$daily=null;foreach((array)($s['directorMarketRates']??[]) as $r)if(($r['date']??'')<=$date&&(!$daily||$r['date']>$daily['date']))$daily=$r;if($daily&&$daily['date']>=($best['date']??'')){$factor=match($daily['purchaseUnit']??'KG'){'MAUND'=>40.,'MT'=>1000.,default=>1.};if(is_numeric($daily['cashPrice']??null))$result['rawRiceRate']=(float)$daily['cashPrice']/$factor;$factor=match($daily['brokenUnit']??'KG'){'MAUND'=>40.,'MT'=>1000.,default=>1.};if(is_numeric($daily['brokenPrice']??null))$by['B2']=(float)$daily['brokenPrice']/$factor;}}
 $result['byProducts']=$by;return $result;
}

/** Aggregate the canonical per-run FIFO without altering receipts or production. */
function mc_fifo_groups(array $s,array $ops,string $entity):array {
 $runs=pc_production($ops,$entity);$fifo=rf_sources($s,$ops,$entity);$out=[];
 foreach($runs as $run){$id=$entity.'|'.$run['date'].'|'.mc_variety($run['variety']);if(!isset($out[$id]))$out[$id]=['available'=>true,'rawValue'=>0.,'inputKg'=>0.,'provisional'=>false,'layers'=>[],'issues'=>[]];$f=$fifo[$run['id']]??[];$out[$id]['available']=$out[$id]['available']&&!empty($f['available']);$out[$id]['rawValue']+=(float)($f['rawValue']??0);$out[$id]['inputKg']+=(float)$run['inputKg'];$out[$id]['provisional']=$out[$id]['provisional']||!empty($f['provisional']);foreach((array)($f['layers']??[]) as $layer)$out[$id]['layers'][]=$layer+['productionId'=>$run['id']];if(empty($f['available']))$out[$id]['issues'][]=$f['status']??'Recorded FIFO purchase cost is missing';}
 return $out;
}
function mc_build(array $s,array $ops,string $entity,?array &$reportSources=null,string $asOf=''):array{
 if($asOf==='')$asOf=(new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi')))->format('Y-m-d');
 $groups=mc_production($ops,$entity);$costGroups=pc_group_production(pc_production($ops,$entity));$actualSources=pc_cost_sources($ops,$costGroups,$s,$entity);$reportSources=$actualSources;$sales=mc_sales($ops,$entity);$fifo=mc_fifo_groups($s,$ops,$entity);$sheets=[];
 foreach($groups as $g){if($g['date']>$asOf)continue;$k=$g['varietyKey'];$need=(float)$g['inputKg'];$f=$fifo[$g['id']]??[];$fifoAvailable=!empty($f['available'])&&$need>0;$provisional=!empty($f['provisional']);$rawRate=$fifoAvailable?(float)$f['rawValue']/$need:0.;$rawSource='Recorded purchase FIFO — consumed lots weighted by kilograms';$input=mc_director_input($s,$entity,$asOf,$k);
 $millRate=TT_MC_MILLING_RATE;$millSource='Estimated mill expenses — Rs 3/kg raw input';$rawValue=round($need*$rawRate,2);$processingRate=0.;$processingValue=round($need*$processingRate,2);$millingValue=round($need*$millRate,2);$by=[];$byValue=0.0;$missing=[];foreach($g['outputs'] as $o){if(!empty($o['ready']))continue;$name=(string)$o['product'];$kg=(float)$o['kg'];if(mc_waste($name)){$by[]=['product'=>$name,'kg'=>$kg,'rate'=>0,'value'=>0,'rateSource'=>'Waste / Nil','saleDate'=>'','saleReference'=>'','party'=>''];continue;}$pk=mc_product($name);$directorRates=(array)($input['byProducts']??[]);$rate=isset($directorRates[$pk])?(float)$directorRates[$pk]:(isset($directorRates[$name])?(float)$directorRates[$name]:0);$src='';$saleDate='';$saleRef='';$party='';$sale=mc_average_sale($sales,$name,$asOf);if($sale){$rate=(float)$sale['rate'];$src='Average recorded selling price';$saleDate=(string)$sale['date'];$saleRef=(string)$sale['reference'];$party=(string)$sale['party'];}elseif($rate>0)$src='Directors by-product price estimate';if($rate<=0){$missing[]=$pk;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>null,'value'=>null,'rateSource'=>'No Directors price or recorded sale','saleDate'=>'','saleReference'=>'','party'=>''];continue;}$value=round($kg*$rate,2);$byValue+=$value;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>$rate,'value'=>$value,'rateSource'=>$src,'saleDate'=>$saleDate,'saleReference'=>$saleRef,'party'=>$party];}$actualCost=0.;$allocatedSources=[];foreach($actualSources as $source){$amount=(float)($source['allocations'][$g['id']]??0);if($amount==0)continue;$actualCost+=$amount;$allocatedSources[]=$source+['allocatedPKR'=>$amount];}$conversion=$millingValue;$readyValue=round($rawValue+$conversion-$byValue,2);$readyRate=$g['readyKg']>0&&$readyValue>0?$readyValue/$g['readyKg']:0;$status='Ready';if(!empty($g['requiresInputStockCost']))$status='Waiting — reprocessing input-stock cost needs review';elseif(empty($g['inputComplete']))$status='Waiting — actual raw input is missing';elseif(!$fifoAvailable)$status='Cost incomplete — '.implode('; ',array_unique($f['issues']??['Recorded FIFO purchase cost is missing']));elseif($rawRate<=0)$status='Waiting — raw rice cost is missing';elseif($g['readyKg']<=0)$status='Waiting — Ready Rice output is missing';elseif($missing)$status='Waiting — Directors price or recorded sale missing for '.implode(', ',array_values(array_unique($missing)));elseif($readyValue<=0)$status='Waiting — by-product value is too high';$sid=mc_sheet_id($entity,$g['date'],$k);$sheets[$sid]=['id'=>$sid,'entity'=>$entity,'date'=>$g['date'],'variety'=>$g['variety'],'varietyKey'=>$k,'inputKg'=>$need,'inputComplete'=>$g['inputComplete'],'readyRiceKg'=>$g['readyKg'],'readyProductQuantities'=>array_column(array_filter($g['outputs'],static fn($o)=>!empty($o['ready'])),'kg','product'),'readyProducts'=>array_values(array_map(static fn($o)=>(string)$o['product'],array_filter($g['outputs'],static fn($o)=>!empty($o['ready'])))),'rawRiceRate'=>$fifoAvailable?round($rawRate,6):null,'rawRiceRateSource'=>$rawSource,'rawRiceValue'=>$fifoAvailable?$rawValue:null,'fifoLayers'=>$f['layers']??[],'rawCostBasis'=>'RECORDED_FIFO','usesProvisionalPurchaseCost'=>$provisional,'millingRatePerKg'=>round($millRate,6),'millingRateSource'=>$millSource,'millingValue'=>$millingValue,'allocatedMillCostPKR'=>round($actualCost,2),'conversionSources'=>$allocatedSources,'conversionCostPKR'=>round($conversion,2),'conversionBasis'=>'Rs 3/kg raw input estimate; recorded actual expenses are separate comparison only','actualComparisonPKR'=>round($actualCost,2),'actualComparisonStatus'=>'Available actual expenses only; reconcile after KE and remaining monthly bills arrive','reportOnly'=>true,'costStatus'=>'ESTIMATE','processingRatePerKg'=>$processingRate,'processingValue'=>$processingValue,'byProducts'=>$by,'byProductValue'=>round($byValue,2),'estimatedReadyRiceValue'=>$status==='Ready'?$readyValue:null,'estimatedReadyRiceCostPerKg'=>$status==='Ready'?round($readyRate,6):null,'missingByProductRates'=>array_values(array_unique($missing)),'status'=>$status,'ready'=>$status==='Ready','sourceMode'=>'Recorded FIFO / Directors by-product estimates','note'=>'Reporting estimate only until all quantities, invoices, expenses and payments are settled. No journal or stock movement is created.'];}return array_values($sheets);}
function mc_sync_management_rates(array &$s,array $sheets):void{$active=[];$perDate=[];foreach($sheets as $sh)if(!empty($sh['ready']))$perDate[$sh['date']][]=$sh;foreach($sheets as $sh){if(empty($sh['ready']))continue;$aliases=array_values(array_unique(array_merge((array)($sh['readyProducts']??[]),[(string)$sh['variety']] )));if(count($perDate[$sh['date']]??[])===1)$aliases[]='Ready Rice';$id=mc_rate_id($sh['id'],(string)$sh['variety']);$active[$id]=true;$s['managementCostRates'][$id]=['id'=>$id,'entity'=>$sh['entity'],'product'=>$sh['variety'],'aliases'=>array_values(array_unique($aliases)),'effectiveFrom'=>$sh['date'],'costPerKg'=>$sh['estimatedReadyRiceCostPerKg'],'inventoryAccount'=>'1320','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'updatedAt'=>gmdate('c')];foreach((array)$sh['byProducts'] as $bp){if($bp['rate']===null||mc_waste((string)$bp['product']))continue;$bid=mc_rate_id($sh['id'],(string)$bp['product']);$active[$bid]=true;$s['managementCostRates'][$bid]=['id'=>$bid,'entity'=>$sh['entity'],'product'=>$bp['product'],'aliases'=>[mc_product((string)$bp['product'])],'effectiveFrom'=>$sh['date'],'costPerKg'=>$bp['rate'],'inventoryAccount'=>'1330','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'updatedAt'=>gmdate('c')];}}foreach($s['managementCostRates'] as $id=>&$r)if(is_array($r)&&($r['entity']??'')===($sheets[0]['entity']??'')&&!isset($active[$id]))$r['status']='Superseded';unset($r);}
function mc_same_sheet(array $a,array $b):bool{foreach(['createdAt','updatedAt'] as $k){unset($a[$k],$b[$k]);}return json_encode($a,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)===json_encode($b,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
function mc_payload(array $s,array $ops,string $entity,string $asOf=''):array{$costSources=[];$sheets=mc_build($s,$ops,$entity,$costSources,$asOf);usort($sheets,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date'])?:strcmp((string)$a['variety'],(string)$b['variety']));return ['ok'=>true,'entity'=>$entity,'sheets'=>$sheets,'unallocatedCosts'=>array_values(array_filter($costSources,static fn($source)=>empty($source['allocations']))),'millingFallbackRate'=>TT_MC_MILLING_RATE,'serverNow'=>gmdate('c')];}
